package hu.bankmonitor.payments.outbox;

/**
 * How an Outbox Event leaves this application, and the one thing that changes when the
 * transport does.
 *
 * <p><b>Swapping a broker in happens under this method, and replaces nothing above it.</b>
 * "Commit to the database, then send to Kafka" is still two writes with no transaction
 * spanning them; the outbox exists because a broker publish cannot join a database
 * transaction, so Kafka is the transport under {@code publish} and not an alternative to
 * the table. Design decision 12 argues it, and {@code docs/deferred.md} names Kafka and
 * Spring Modulith's Event Publication Registry as the production answers.
 *
 * <p><b>The one caller is the poller</b>, which is package-private. That is deliberate: the
 * only way to reach this method with an event is to have written the event down first, so
 * "published but not committed" is not a state any caller can produce.
 *
 * <p><b>An implementation must not mark the event sent</b>, and cannot — {@link OutboxEvent}
 * has no mutator and the row is the poller's to update afterwards. A transport that recorded
 * its own success would record it for a publish that half happened, and the failure this
 * design accepts is a duplicate rather than a loss.
 *
 * <p>Failure is reported by throwing. The event stays unsent and the next run tries again,
 * which is the whole of the retry policy: backoff, a dead-letter path and ordering between
 * two events on one Transfer are deferred, with reasoning, in {@code docs/deferred.md}.
 */
public interface EventPublisher {

	/**
	 * Delivers one event to the outside world.
	 *
	 * <p>Delivery is <b>at-least-once</b>, deliberately. An implementation may be called
	 * again with an event it has already delivered — after a publish that succeeded and a
	 * mark that did not commit, or after a restart — so consumers deduplicate. They must
	 * anyway: exactly-once across a network is not something a retry can buy.
	 *
	 * @throws RuntimeException if the event could not be delivered, which leaves the row
	 *         unsent for the next run
	 */
	void publish(OutboxEvent event);
}
package hu.bankmonitor.payments.outbox;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Component;

/**
 * The transport this build ships: one log line per event.
 *
 * <p>It is a real implementation of {@link EventPublisher} rather than a stub, and the
 * distinction matters to what a reviewer can conclude. The outbox, the poller and the
 * at-least-once contract above it all run exactly as they would against a broker; the only
 * thing that is not real is the far end. Design decision 31 makes this line the whole of
 * the observability story alongside the Actuator health endpoint.
 *
 * <p>The line names every field a consumer would receive, so what went out is legible in
 * the log rather than inferable from the table it left. The payload is included whole for
 * the same reason — these are Transfer amounts and account identifiers in a service with no
 * authentication and demo data behind it, so there is nothing here a log may not hold.
 */
@Component
class LoggingEventPublisher implements EventPublisher {

	private static final Logger log = LoggerFactory.getLogger(LoggingEventPublisher.class);

	@Override
	public void publish(OutboxEvent event) {
		log.info("Published outbox event id={} type={} transferId={} occurredAt={} payload={}",
				event.getId(), event.getEventType(), event.getTransferId(),
				event.getOccurredAt(), event.getPayload());
	}
}
package hu.bankmonitor.payments.outbox;

import org.springframework.data.domain.Limit;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.Repository;
import org.springframework.transaction.annotation.Transactional;

import java.time.Instant;
import java.util.List;

/**
 * Persistence for {@link OutboxEvent}, package-private so that reaching it from another
 * slice does not compile (design decision 30).
 *
 * <p>The bare {@link Repository} marker rather than {@code JpaRepository}, on {@code
 * Account}'s precedent: it declares nothing, so every method here is one with a call site
 * today.
 */
interface OutboxEventRepository extends Repository<OutboxEvent, Long> {

	/** Writes one event, which happens only inside the transaction of the change it describes. */
	OutboxEvent save(OutboxEvent event);

	/**
	 * The next events nobody has published, oldest first — the poller's whole query.
	 *
	 * <p>It is bounded because the table only grows — archival is one of the four deferrals
	 * {@code docs/deferred.md} records against this slice — so an unbounded read would one
	 * day load the history of the system into a scheduled method. What the limit costs is
	 * nothing: the rows it leaves behind are still unsent, and the next run is a second away.
	 *
	 * <p>The ordering is by insertion and not by {@code occurredAt}: it decides which rows a
	 * bounded read takes, so it has to be total, and two events written in one transaction
	 * share an instant. It is <em>not</em> a delivery-order guarantee — publishing is
	 * at-least-once and a failure mid-batch reorders the retry. Ordering between two events
	 * on one Transfer is deferred, and consumers are expected to tolerate its absence.
	 */
	List<OutboxEvent> findBySentAtIsNullOrderByIdAsc(Limit limit);

	/**
	 * Marks one event published, and reports whether this call was the one that did it.
	 *
	 * <p><b>{@code sentAt is null} is the guard</b>, on {@code CheckLedgerRepository.answer}'s
	 * precedent. Nothing today can lose that race — one instance runs one poll at a time — but
	 * the row is the only place the fact lives, and a second instance reading the same unsent
	 * rows is a named break of the single-instance assumption rather than an impossibility.
	 * Under the guard the second writer changes nothing instead of overwriting a timestamp
	 * that already said when the event went out.
	 *
	 * <p>It carries its own transaction because the poller runs outside one. Publishing is
	 * I/O, and holding a transaction open across it — trivially a log line here, a broker
	 * round trip once {@code publish} is swapped — is the shape {@code AccountLocking} exists
	 * to keep out of the locked path. So each row is published first and marked second, each
	 * mark in a transaction of its own: that ordering is what makes delivery at-least-once
	 * rather than at-most-once, and a mark that never commits costs a duplicate consumers
	 * already have to tolerate.
	 */
	@Transactional
	@Modifying
	@Query("""
			UPDATE OutboxEvent event SET event.sentAt = :sentAt
			WHERE event.id = :id
			  AND event.sentAt IS NULL
			""")
	int markSent(Long id, Instant sentAt);
}
package hu.bankmonitor.payments.outbox;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.data.domain.Limit;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

import java.time.Clock;

/**
 * What drains the outbox: every unsent event, published and then marked sent.
 *
 * <p>It is package-private, which is design decision 30's line for this slice. Nothing
 * outside calls a poller — it is woken by the scheduler, and the only reason to reach it
 * from elsewhere would be to make it run, which is a thing tests in this package can do and
 * production has no use for.
 *
 * <p><b>Publish first, mark second, and neither inside the other's transaction.</b> That
 * order is the whole of the at-least-once contract. Marking first would make delivery
 * at-most-once: a publish that then failed would leave a row saying it had gone out. Doing
 * both in one transaction would hold it open across the publish — a log line today, a broker
 * round trip once the transport is swapped — which is the shape {@code AccountLocking} exists
 * to keep off the locked path, and would still not make the pair atomic, because a broker
 * cannot join a transaction. So the failure this design accepts is a duplicate, and
 * consumers deduplicate, which they must anyway.
 *
 * <p><b>A publish that throws costs its own row and no other.</b> The run logs it, leaves it
 * unsent and carries on: stopping at the first failure would let one undeliverable event hold
 * up every event behind it, and there is no ordering guarantee here for it to be protecting.
 * Retrying it immediately on the next run is the entire retry policy — backoff and a
 * dead-letter path for a row that can never be delivered are deferred, with reasoning, in
 * {@code docs/deferred.md}.
 *
 * <p><b>One instance is assumed.</b> Two would read the same unsent rows and publish them
 * twice; the fix is {@code SELECT … FOR UPDATE SKIP LOCKED} on the poll query, and it is one
 * of the two named breaks of the single-instance assumption in {@code docs/deferred.md}. The
 * guard on {@link OutboxEventRepository#markSent} narrows what that costs but does not close
 * it — it stops a second timestamp being written, not a second publish.
 */
@Component
class OutboxPoller {

	/**
	 * How many events one run takes.
	 *
	 * <p>A cap rather than everything unsent, because archival is deferred and the table only
	 * grows: an unbounded read would eventually pull the history of the system into a
	 * scheduled method. Nothing is lost by the cap — what it leaves behind is still unsent,
	 * and the next run is one delay away.
	 */
	private static final Limit ONE_RUN = Limit.of(100);

	private static final Logger log = LoggerFactory.getLogger(OutboxPoller.class);

	private final OutboxEventRepository events;

	private final EventPublisher publisher;

	private final Clock clock;

	OutboxPoller(OutboxEventRepository events, EventPublisher publisher, Clock clock) {
		this.events = events;
		this.publisher = publisher;
		this.clock = clock;
	}

	/**
	 * Publishes what has not gone out yet, and records that it has.
	 *
	 * <p>The method is public so that no proxy strategy can decide it is not worth advising,
	 * on the reasoning {@code hu.bankmonitor.payments} documents for {@code @Transactional}.
	 * The class it sits on is package-private, so this widens nothing.
	 *
	 * <p>{@code fixedDelay} rather than {@code fixedRate}: the delay is measured from the end
	 * of the previous run, so runs cannot overlap and a slow batch cannot have a second one
	 * publishing the rows it is still working through.
	 */
	@Scheduled(fixedDelayString = "${payments.outbox.poll-delay}")
	public void publishUnsentEvents() {
		for (OutboxEvent event : events.findBySentAtIsNullOrderByIdAsc(ONE_RUN)) {
			if (published(event)) {
				events.markSent(event.getId(), clock.instant());
			}
		}
	}

	private boolean published(OutboxEvent event) {
		try {
			publisher.publish(event);
			return true;
		}
		catch (RuntimeException failure) {
			log.error("Outbox event id={} could not be published and stays unsent", event.getId(), failure);
			return false;
		}
	}
}
